//! The stance HUD as sprites and flat bands: which parts are drawn, where, and with which palette.
//!
//! The art lives in `assets/hud/sprites/stance_hud_art.rs`, generated by `showcase-vector/hudart`.
//! Every repeated part (a health cell, a gem) is one sprite drawn at a fixed step, and a colour
//! state (lit, empty, the other stance) is a different palette over the same texels, so two parts in
//! different states are the same pixels by construction. Axis-aligned areas are flat rectangles, so
//! nothing here depends on how the GPU fills a slanted triangle.
//!
//! The composition is written once against a `draw` callback, like `stance_hud_layout.rs`: the guest
//! turns each [`Op`] into a packet, the host viewer (`hudart`'s `hudview`) paints them into a frame.
//! This file has no dependencies, so both include it by path.

/// A rectangle of the atlas, in texels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SpriteRect {
    pub u: u8,
    pub v: u8,
    pub w: u8,
    pub h: u8,
}

/// Rows `y0..y1` of a bar plate in one flat colour.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Band {
    pub y0: u8,
    pub y1: u8,
    pub rgb: [u8; 3],
}

include!("../assets/hud/sprites/stance_hud_art.rs");

/// The two stances. The one in front shows its own colours; the one behind is dimmed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Stance {
    Horizon,
    Zenith,
}

impl Stance {
    const fn index(self) -> usize {
        match self {
            Self::Horizon => 0,
            Self::Zenith => 1,
        }
    }

    const fn other(self) -> Self {
        match self {
            Self::Horizon => Self::Zenith,
            Self::Zenith => Self::Horizon,
        }
    }
}

/// Everything the HUD shows; packets built from it stay valid while it is equal.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HudState {
    /// The stance in front.
    pub stance: Stance,
    /// Lit health cells of the front stance, 0 to [`COUNT`].
    pub health: u8,
    /// Lit health cells of the stance behind.
    pub back_health: u8,
    /// Lit energy gems.
    pub energy: u8,
}

/// One thing to paint, in screen pixels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    /// A flat rectangle.
    Rect {
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        rgb: [u8; 3],
    },
    /// A sprite from the atlas, drawn 1:1 with CLUT number `clut` of [`CLUTS`].
    Sprite {
        x: i32,
        y: i32,
        src: SpriteRect,
        clut: usize,
    },
}

/// Ops one HUD needs at most: every band of both bars, both caps, both bars' cells, the emblem
/// and the gems.
pub const MAX_OPS: usize = 2 * BAND_COUNT + 2 + 3 * (COUNT as usize) + 1;

fn bar(origin: (i32, i32), front: bool, stance: Stance, lit: u8, draw: &mut impl FnMut(Op)) {
    let top = origin.1 + if front { FRONT_Y } else { 0 };
    // The bar behind shows only the rows above the one in front.
    let rows = if front { BAR_H } else { BACK_OFFSET };
    let kind = if front { 0 } else { 1 };
    let s = stance.index();
    for band in &BANDS[s][kind] {
        let y1 = (band.y1 as i32).min(rows);
        if (band.y0 as i32) < y1 {
            draw(Op::Rect {
                x: origin.0 + BAR_X0,
                y: top + band.y0 as i32,
                w: CAP_X - BAR_X0,
                h: y1 - band.y0 as i32,
                rgb: band.rgb,
            });
        }
    }
    let base = s * CLUTS_PER_STANCE;
    let (cap_clut, lit_clut, empty_clut) = if front {
        (CLUT_FRONT_CAP, CLUT_FRONT_CELL_LIT, CLUT_FRONT_CELL_EMPTY)
    } else {
        (CLUT_BACK_CAP, CLUT_BACK_CELL_LIT, CLUT_BACK_CELL_EMPTY)
    };
    draw(Op::Sprite {
        x: origin.0 + CAP_X,
        y: top,
        src: SpriteRect {
            h: (SPRITE_CAP.h as i32).min(rows) as u8,
            ..SPRITE_CAP
        },
        clut: base + cap_clut,
    });
    let cell_rows = (rows - CELL_ROW).min(SPRITE_CELL.h as i32);
    if cell_rows <= 0 {
        return;
    }
    let src = SpriteRect {
        h: cell_rows as u8,
        ..SPRITE_CELL
    };
    for k in 0..COUNT {
        draw(Op::Sprite {
            x: origin.0 + CELL_X0 + PITCH * k,
            y: top + CELL_ROW,
            src,
            clut: base
                + if (k as u8) < lit {
                    lit_clut
                } else {
                    empty_clut
                },
        });
    }
}

/// Paint the HUD with its top-left at `origin`, back to front: the bar behind, the bar in front, the
/// emblem, the gems.
pub fn compose(origin: (i32, i32), state: &HudState, draw: &mut impl FnMut(Op)) {
    bar(origin, false, state.stance.other(), state.back_health, draw);
    bar(origin, true, state.stance, state.health, draw);
    draw(Op::Sprite {
        x: origin.0 + EMBLEM_X,
        y: origin.1 + EMBLEM_Y,
        src: SPRITE_EMBLEM,
        clut: state.stance.index() * CLUTS_PER_STANCE + CLUT_EMBLEM,
    });
    for k in 0..COUNT {
        draw(Op::Sprite {
            x: origin.0 + GEM_X0 + PITCH * k,
            y: origin.1 + GEM_Y,
            src: SPRITE_GEM,
            clut: if (k as u8) < state.energy {
                CLUT_GEM_LIT
            } else {
                CLUT_GEM_EMPTY
            },
        });
    }
}
